create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,employee_number text unique,role text not null default 'field_worker' check(role in('admin','supervisor','field_worker')),area text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.work_records(id uuid primary key default gen_random_uuid(),record_number text,work_description text not null,old_meter_number text,old_meter_reading numeric,new_meter_number text,new_meter_reading numeric,record_date date not null default current_date,latitude double precision,longitude double precision,location_accuracy double precision,created_by uuid not null references auth.users(id),status text not null default 'new' check(status in('new','submitted','approved','rejected')),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.record_photos(id uuid primary key default gen_random_uuid(),record_id uuid not null references public.work_records(id) on delete cascade,photo_type text,file_path text not null,latitude double precision,longitude double precision,taken_at timestamptz,created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email)) on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.current_role() returns text language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid(); $$;
alter table public.profiles enable row level security;alter table public.work_records enable row level security;alter table public.record_photos enable row level security;
create policy "profile self read" on public.profiles for select to authenticated using(id=auth.uid() or public.current_role() in('admin','supervisor'));
create policy "admin profiles update" on public.profiles for update to authenticated using(public.current_role()='admin') with check(public.current_role()='admin');
create policy "records select" on public.work_records for select to authenticated using(created_by=auth.uid() or public.current_role() in('admin','supervisor'));
create policy "records insert" on public.work_records for insert to authenticated with check(created_by=auth.uid());
create policy "records update" on public.work_records for update to authenticated using(created_by=auth.uid() or public.current_role() in('admin','supervisor')) with check(created_by=auth.uid() or public.current_role() in('admin','supervisor'));
create policy "records delete admin" on public.work_records for delete to authenticated using(public.current_role()='admin');
create policy "photos select" on public.record_photos for select to authenticated using(exists(select 1 from public.work_records r where r.id=record_id and(r.created_by=auth.uid() or public.current_role() in('admin','supervisor'))));
create policy "photos insert" on public.record_photos for insert to authenticated with check(exists(select 1 from public.work_records r where r.id=record_id and r.created_by=auth.uid()));
create policy "photos delete" on public.record_photos for delete to authenticated using(exists(select 1 from public.work_records r where r.id=record_id and(r.created_by=auth.uid() or public.current_role()='admin')));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('meter-photos','meter-photos',false,10485760,array['image/jpeg','image/png','image/webp','image/heic']) on conflict(id) do update set public=false;
create policy "storage authenticated read" on storage.objects for select to authenticated using(bucket_id='meter-photos');
create policy "storage authenticated upload" on storage.objects for insert to authenticated with check(bucket_id='meter-photos');
create policy "storage authenticated delete" on storage.objects for delete to authenticated using(bucket_id='meter-photos');
